let root: string;
let workspace: Workspace;
before(async () => {
  root = await fs.realpath(await fs.mkdtemp(path.join(tmpdir(), "codaryn-c4-equivalence-")));
  for (const [file, value] of Object.entries(FIXTURES)) {
    const at = path.join(root, file);
    await fs.mkdir(path.dirname(at), { recursive: true });
    await fs.writeFile(at, typeof value === "string" ? value : Buffer.from(value));
  }
  workspace = await createWorkspace({ root });
});
after(async () => { await fs.rm(root, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 }); });
for (const c of CASES) test("C4 byte equivalence: " + c.id, async () => {
  const signal = new AbortController().signal;
  const limits = { chunkBytes: c.chunkBytes ?? 7, ...(c.maxBytes === undefined ? {} : { maxTableBytes: c.maxBytes }) };
  let result: unknown;
  if (c.kind === "query") {
    assert.ok(c.args);
    result = await queryTableTool({ workspace, minGroupSize: 5, ...limits, ...(c.hidden ? { unreadable: compilePathSet(c.hidden, { match: "prefix", onUnusable: "covers" }) } : {}) }, c.args, signal);
  } else {
    assert.ok(c.rules);
    result = await runDataChecksVerifier({ id: "c4", kind: "data_checks", rules: c.rules }, workspace, signal, { ...limits, minGroupSize: 5, ...(c.hidden ? { unreadablePaths: c.hidden } : {}) });
  }
  assert.equal(JSON.stringify(result), GOLDEN[c.id], c.id + ": output/evidence bytes must stay unchanged");
});
